mapper.select:
SELECT

FROM shop_store s

    s.is_deleted = 0

        AND s.store_type = #{q.storeType}


        AND s.business_status = #{q.businessStatus}


        AND s.status = #{q.status}



        AND (s.user_id = #{q.currentUserId} OR s.manager_id = #{q.currentUserId})



        AND (s.store_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR s.store_code LIKE CONCAT('%', #{q.keyword}, '%'))



ORDER BY s.status DESC, s.sort ASC, s.id DESC
